INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5252edce7737e85b', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Urban trees', NULL, NULL, NULL, NULL, '{"text":"Urban trees do more than beautify a city; they cool the air, filter pollutants, and provide habitat for wildlife, making dense neighbourhoods far more liveable."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_30d45f5506d18c5e', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Scientific method', NULL, NULL, NULL, NULL, '{"text":"The scientific method relies on forming a hypothesis, testing it through controlled experiments, and revising conclusions when the evidence demands it."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_8cbb13116eb62278', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Ocean currents', NULL, NULL, NULL, NULL, '{"text":"Ocean currents redistribute heat around the planet, influencing regional climates and shaping the migration patterns of countless marine species."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_514fcb7078ef8000', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Digital archives', NULL, NULL, NULL, NULL, '{"text":"Digital archives preserve fragile documents, yet they demand constant maintenance because file formats and storage media rapidly become obsolete."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_8e9190f0f6829ac9', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Renewable energy', NULL, NULL, NULL, NULL, '{"text":"As the cost of solar panels continues to fall, renewable energy is becoming an increasingly practical alternative to fossil fuels in many regions."}', 2, 1, '[]', datetime('now'), datetime('now'));
