INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_34312a252fb1a731', 'SPEAKING', 'DESCRIBE_IMAGE', 'Describe Image — Rainfall', NULL, NULL, '/uploads/seed/img4.svg', 'image', '{"keyPoints":["monthly rainfall","wettest in winter","driest in summer","clear seasonal pattern"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_c093a13c4d1df48f', 'SPEAKING', 'DESCRIBE_IMAGE', 'Describe Image — Sales by region', NULL, NULL, '/uploads/seed/img5.svg', 'image', '{"keyPoints":["sales across regions","north leads","west trails","overall differences"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_cabdb8d03e621ff2', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Bee communication', NULL, 'Honeybees communicate the location of food through a remarkable behaviour known as the waggle dance. By varying the angle and duration of the dance, a returning forager tells the rest of the hive both the direction and the distance of a flower patch relative to the sun. This efficient signalling system allows a colony to concentrate its efforts on the richest sources of nectar.', NULL, 'audio', '{"keyPoints":["waggle dance","angle shows direction relative to the sun","duration shows distance","colony focuses on best nectar"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_273acb8f7249d679', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Memory consolidation', NULL, 'During sleep, the brain replays the experiences of the day, strengthening the neural connections that underlie new memories. This process, called consolidation, transfers information from short-term storage in the hippocampus to more durable networks in the cortex. Studies show that people who sleep after learning retain significantly more than those who stay awake.', NULL, 'audio', '{"keyPoints":["sleep replays daily experiences","consolidation strengthens connections","hippocampus to cortex","sleep improves retention"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_14c9afca8b1d0359', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Coral bleaching', NULL, 'Coral reefs owe their colour to tiny algae that live inside them and supply most of their food. When ocean temperatures rise even slightly, the corals expel these algae and turn white, a phenomenon called bleaching. If warm conditions persist, the starved corals eventually die, threatening the vast biodiversity that depends on the reef.', NULL, 'audio', '{"keyPoints":["algae give colour and food","warming causes coral to expel algae","bleaching turns coral white","prolonged warmth kills reefs"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_1a7ee5bee34bef2f', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — The printing press', NULL, 'The invention of the printing press in the fifteenth century dramatically lowered the cost of books and accelerated the spread of ideas across Europe. Literacy expanded beyond the clergy and the wealthy, fuelling scientific exchange and religious reform. Historians often regard it as one of the most consequential technologies in human history.', NULL, 'audio', '{"keyPoints":["printing press lowered book costs","ideas spread across Europe","literacy expanded","fuelled science and reform"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7d23fd9164a672ae', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Urban heat islands', NULL, 'Cities tend to be warmer than the surrounding countryside, an effect known as the urban heat island. Dark roofs and paved surfaces absorb sunlight during the day and release it slowly at night, while a lack of vegetation reduces natural cooling. Planners increasingly use reflective materials and green spaces to counter the problem.', NULL, 'audio', '{"keyPoints":["cities warmer than countryside","dark surfaces absorb heat","little vegetation reduces cooling","reflective materials and greenery help"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7028820e8561e752', 'SPEAKING', 'ANSWER_SHORT_QUESTION', 'ASQ — Frozen water', NULL, 'What do we call water that has frozen solid?', NULL, 'audio', '{"question":"What do we call water that has frozen solid?","acceptedAnswers":["ice"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_fa5f434c648748e1', 'SPEAKING', 'ANSWER_SHORT_QUESTION', 'ASQ — Star at the centre', NULL, 'Which star lies at the centre of our solar system?', NULL, 'audio', '{"question":"Which star lies at the centre of our solar system?","acceptedAnswers":["the sun","sun"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_6bf3f112044e3680', 'SPEAKING', 'ANSWER_SHORT_QUESTION', 'ASQ — Study of plants', NULL, 'What is the scientific study of plants called?', NULL, 'audio', '{"question":"What is the scientific study of plants called?","acceptedAnswers":["botany"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_350566c3c849f4dc', 'SPEAKING', 'ANSWER_SHORT_QUESTION', 'ASQ — Days in a week', NULL, 'How many days are there in a week?', NULL, 'audio', '{"question":"How many days are there in a week?","acceptedAnswers":["seven","7"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_2dc2203488ad3093', 'SPEAKING', 'ANSWER_SHORT_QUESTION', 'ASQ — Person who teaches', NULL, 'What do we call a person whose job is to teach students at a university?', NULL, 'audio', '{"question":"What do we call a person who teaches at a university?","acceptedAnswers":["lecturer","professor","teacher"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0d5629620021eb8c', 'WRITING', 'SUMMARIZE_WRITTEN_TEXT', 'SWT — Sleep and health', NULL, NULL, NULL, NULL, '{"passage":"Chronic sleep deprivation has been linked to a wide range of health problems, including obesity, weakened immunity, and impaired concentration. Researchers argue that adults consistently underestimate how much sleep they need, treating rest as expendable when work or social demands increase. Public-health campaigns, they suggest, should promote sleep with the same urgency as diet and exercise."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_403973fe2784d946', 'WRITING', 'SUMMARIZE_WRITTEN_TEXT', 'SWT — Remote work', NULL, NULL, NULL, NULL, '{"passage":"The rapid shift to remote work has reshaped how organisations operate. While employees often report greater flexibility and reduced commuting stress, managers worry about weaker collaboration and the blurring of boundaries between work and home. Many companies are now experimenting with hybrid models that attempt to preserve the benefits of both arrangements."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_c7bfed9c20d11481', 'WRITING', 'SUMMARIZE_WRITTEN_TEXT', 'SWT — Plastic pollution', NULL, NULL, NULL, NULL, '{"passage":"Plastic waste accumulates in oceans because it is durable, cheap, and rarely recycled effectively. Once in the water, larger items break into microplastics that enter the food chain and prove almost impossible to remove. Scientists emphasise that reducing production and improving waste management are far more effective than clean-up efforts alone."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_40681f5e7735b122', 'WRITING', 'SUMMARIZE_WRITTEN_TEXT', 'SWT — Bilingualism', NULL, NULL, NULL, NULL, '{"passage":"Growing up with two languages was once thought to confuse children, but modern research suggests the opposite. Bilingual individuals tend to show stronger executive control, switching between tasks more efficiently and filtering distractions more effectively. Some studies even indicate that lifelong bilingualism may delay the onset of dementia by several years."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_848b016061b450a3', 'WRITING', 'SUMMARIZE_WRITTEN_TEXT', 'SWT — The gig economy', NULL, NULL, NULL, NULL, '{"passage":"The gig economy offers workers the freedom to choose when and how much they work, an arrangement many find appealing. However, this flexibility often comes without the protections of traditional employment, such as paid leave, pensions, or job security. Policymakers face the difficult task of extending basic safeguards without eliminating the flexibility that makes gig work attractive."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_3d0c0d1622e38b2a', 'WRITING', 'WRITE_ESSAY', 'Essay — Technology and communication', NULL, NULL, NULL, NULL, '{"prompt":"Some people believe that modern technology has made human communication shallower, while others argue it has brought people closer together. Discuss both views and give your own opinion. Write 200–300 words."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7b34c771bc9f9798', 'WRITING', 'WRITE_ESSAY', 'Essay — University for everyone', NULL, NULL, NULL, NULL, '{"prompt":"A university education should be free and available to everyone who wishes to study. To what extent do you agree or disagree? Support your position with reasons and examples. Write 200–300 words."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7cfcd211b6a39e66', 'WRITING', 'WRITE_ESSAY', 'Essay — Remote work', NULL, NULL, NULL, NULL, '{"prompt":"Do the advantages of working from home outweigh the disadvantages? Discuss with reference to both employees and employers. Write 200–300 words."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_12e4161a7fbcd36d', 'WRITING', 'WRITE_ESSAY', 'Essay — Environmental responsibility', NULL, NULL, NULL, NULL, '{"prompt":"Who should bear the greatest responsibility for reducing pollution: individuals, corporations, or governments? Give reasons for your answer. Write 200–300 words."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0dc07cd84eb9e104', 'WRITING', 'WRITE_ESSAY', 'Essay — Study abroad', NULL, NULL, NULL, NULL, '{"prompt":"Studying abroad benefits students far more than studying in their home country. To what extent do you agree or disagree? Write 200–300 words."}', 2, 1, '[]', datetime('now'), datetime('now'));
