INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_43fe6ec98287f49f', 'READING', 'RW_FILL_BLANKS', 'R&W FIB — Exercise', NULL, NULL, NULL, NULL, '{"text":"Regular exercise not only {{b1}} physical health but also {{b2}} mood by triggering the {{b3}} of endorphins.","blanks":[{"id":"b1","answer":"improves"},{"id":"b2","answer":"boosts"},{"id":"b3","answer":"release"}],"wordBank":["improves","boosts","release","reduces","lowers","storage"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_79ba21cbfd42697d', 'READING', 'RW_FILL_BLANKS', 'R&W FIB — Migration', NULL, NULL, NULL, NULL, '{"text":"Many birds {{b1}} thousands of kilometres each year, {{b2}} the seasons to find abundant food and suitable {{b3}} sites.","blanks":[{"id":"b1","answer":"migrate"},{"id":"b2","answer":"following"},{"id":"b3","answer":"breeding"}],"wordBank":["migrate","following","breeding","remain","ignoring","feeding"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_d2608564f8be6a84', 'READING', 'MCQ_SINGLE_R', 'MCQ (single) — Bees', 'Read the passage and answer the question.', 'Bees are essential pollinators, transferring pollen between flowers and enabling the reproduction of many crops. A decline in bee populations therefore threatens global food security.', NULL, NULL, '{"question":"What is the main idea of the passage?","options":[{"id":"a","text":"Bees are dangerous to crops."},{"id":"b","text":"Bees play a vital role in pollination and food production."},{"id":"c","text":"Bees are increasing in number."},{"id":"d","text":"Bees only pollinate wild flowers."}],"correctOptionId":"b"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_76f9158f65f8d562', 'READING', 'MCQ_SINGLE_R', 'MCQ (single) — Rivers', NULL, 'The delta forms where a river deposits sediment as it enters a larger, calmer body of water. Over centuries, these deposits build fertile land that has long attracted human settlement.', NULL, NULL, '{"question":"Why are deltas often densely settled?","options":[{"id":"a","text":"They are rich in sediment and fertile."},{"id":"b","text":"They are always at high altitude."},{"id":"c","text":"They never flood."},{"id":"d","text":"They lack fresh water."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7e2b7399ae4780de', 'READING', 'MCQ_SINGLE_R', 'MCQ (single) — Antibiotics', NULL, 'Overusing antibiotics accelerates the evolution of resistant bacteria, because the drugs kill vulnerable strains and leave hardier ones to multiply.', NULL, NULL, '{"question":"What does antibiotic overuse encourage?","options":[{"id":"a","text":"The extinction of all bacteria."},{"id":"b","text":"The spread of resistant bacteria."},{"id":"c","text":"Faster healing in every case."},{"id":"d","text":"Weaker bacteria only."}],"correctOptionId":"b"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_084420cb17d649a3', 'READING', 'MCQ_SINGLE_R', 'MCQ (single) — Glaciers', NULL, 'Glaciers act as natural reservoirs, storing water as ice in winter and releasing it gradually in summer. Communities downstream rely on this steady flow for agriculture.', NULL, NULL, '{"question":"What function do glaciers serve for downstream communities?","options":[{"id":"a","text":"They block rivers permanently."},{"id":"b","text":"They provide a steady seasonal water supply."},{"id":"c","text":"They cause year-round drought."},{"id":"d","text":"They have no effect on rivers."}],"correctOptionId":"b"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_1068874ceae8a72c', 'READING', 'MCQ_SINGLE_R', 'MCQ (single) — Advertising', NULL, 'Advertisers increasingly tailor messages to individuals using data about their browsing habits, a practice that raises clear concerns about privacy.', NULL, NULL, '{"question":"What concern does targeted advertising raise?","options":[{"id":"a","text":"Privacy."},{"id":"b","text":"Lower prices."},{"id":"c","text":"Slower internet."},{"id":"d","text":"Better spelling."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0a757e365f809ccf', 'READING', 'MCQ_MULTI_R', 'MCQ (multiple) — Renewable energy', NULL, 'Renewable sources such as solar and wind produce little direct pollution and are effectively inexhaustible. However, their output varies with the weather, and building the infrastructure requires significant upfront investment.', NULL, NULL, '{"question":"Which statements are supported by the passage? (Select all that apply.)","options":[{"id":"a","text":"Renewables produce little direct pollution."},{"id":"b","text":"Renewables are effectively inexhaustible."},{"id":"c","text":"Renewable output is perfectly constant."},{"id":"d","text":"Renewables require upfront investment."}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_d2dfc8bc90dab9ca', 'READING', 'MCQ_MULTI_R', 'MCQ (multiple) — Reading habits', NULL, 'Regular reading expands vocabulary, improves concentration, and exposes readers to diverse perspectives. It does not, however, guarantee academic success on its own.', NULL, NULL, '{"question":"According to the passage, reading can: (Select all that apply.)","options":[{"id":"a","text":"expand vocabulary"},{"id":"b","text":"improve concentration"},{"id":"c","text":"guarantee academic success"},{"id":"d","text":"expose readers to diverse perspectives"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_1efb98dd190c2a68', 'READING', 'MCQ_MULTI_R', 'MCQ (multiple) — Cities', NULL, 'Compact cities can reduce car dependence and preserve surrounding farmland. Critics counter that high density may raise housing costs and strain local services.', NULL, NULL, '{"question":"Which points appear in the passage? (Select all that apply.)","options":[{"id":"a","text":"Compact cities can reduce car dependence."},{"id":"b","text":"Density can raise housing costs."},{"id":"c","text":"Density always lowers costs."},{"id":"d","text":"Compact cities can preserve farmland."}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_f4b849e3537aa1f9', 'READING', 'MCQ_MULTI_R', 'MCQ (multiple) — Volunteering', NULL, 'Volunteering builds social connections and can develop practical skills valued by employers. Yet it demands time that some people struggle to spare.', NULL, NULL, '{"question":"The passage mentions that volunteering: (Select all that apply.)","options":[{"id":"a","text":"builds social connections"},{"id":"b","text":"can develop practical skills"},{"id":"c","text":"requires no time at all"},{"id":"d","text":"demands time"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0356c3dc2e19f3f9', 'READING', 'MCQ_MULTI_R', 'MCQ (multiple) — Tourism', NULL, 'Tourism can boost local economies and fund conservation, but heavy visitor numbers may damage fragile sites and inflate prices for residents.', NULL, NULL, '{"question":"Which effects of tourism are stated? (Select all that apply.)","options":[{"id":"a","text":"boosts local economies"},{"id":"b","text":"can fund conservation"},{"id":"c","text":"always lowers resident prices"},{"id":"d","text":"may damage fragile sites"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_76783ea138e95207', 'READING', 'REORDER_PARAGRAPHS', 'Re-order — Photosynthesis', NULL, NULL, NULL, NULL, '{"items":[{"id":"s1","text":"Photosynthesis is the process by which green plants make their own food."},{"id":"s2","text":"It begins when chlorophyll in the leaves captures energy from sunlight."},{"id":"s3","text":"This energy is used to convert carbon dioxide and water into glucose."},{"id":"s4","text":"The glucose then fuels the plant''s growth, while oxygen is released as a by-product."}],"correctOrder":["s1","s2","s3","s4"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_13f8d73bc7acbfcf', 'READING', 'REORDER_PARAGRAPHS', 'Re-order — Coffee history', NULL, NULL, NULL, NULL, '{"items":[{"id":"s1","text":"According to legend, coffee was discovered by an Ethiopian goat herder."},{"id":"s2","text":"He noticed that his goats became lively after eating certain berries."},{"id":"s3","text":"Curious, he tried the berries himself and felt unusually alert."},{"id":"s4","text":"Word of the energising fruit eventually spread across the Arab world."}],"correctOrder":["s1","s2","s3","s4"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_1cd0848b97b1a4c2', 'READING', 'REORDER_PARAGRAPHS', 'Re-order — The experiment', NULL, NULL, NULL, NULL, '{"items":[{"id":"s1","text":"The researchers first formulated a clear hypothesis."},{"id":"s2","text":"They then designed an experiment to test it under controlled conditions."},{"id":"s3","text":"After collecting the data, they analysed the results statistically."},{"id":"s4","text":"Finally, they published their conclusions for others to review."}],"correctOrder":["s1","s2","s3","s4"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_ca1eae014680e9a7', 'READING', 'REORDER_PARAGRAPHS', 'Re-order — Recycling', NULL, NULL, NULL, NULL, '{"items":[{"id":"s1","text":"Recycling begins when households sort their waste into separate bins."},{"id":"s2","text":"Collection trucks then transport the materials to a sorting facility."},{"id":"s3","text":"There, machines and workers separate paper, glass, and plastics."},{"id":"s4","text":"The sorted materials are finally processed into new products."}],"correctOrder":["s1","s2","s3","s4"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_9784ea61b385991c', 'READING', 'REORDER_PARAGRAPHS', 'Re-order — Job application', NULL, NULL, NULL, NULL, '{"items":[{"id":"s1","text":"The candidate first submitted an application and a tailored résumé."},{"id":"s2","text":"A recruiter reviewed the documents and shortlisted promising applicants."},{"id":"s3","text":"Those selected were invited to a series of interviews."},{"id":"s4","text":"The strongest candidate was then offered the position."}],"correctOrder":["s1","s2","s3","s4"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_8c187a28f93ef501', 'READING', 'R_FILL_BLANKS', 'R FIB — Experiment', NULL, NULL, NULL, NULL, '{"text":"The experiment was {{b1}} under carefully controlled {{b2}}, and the results were {{b3}} recorded for later analysis.","blanks":[{"id":"b1","answer":"conducted","options":["conducted","avoided","ignored"]},{"id":"b2","answer":"conditions","options":["conditions","chances","reasons"]},{"id":"b3","answer":"meticulously","options":["meticulously","carelessly","rarely"]}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_50a43339db5b4a11', 'READING', 'R_FILL_BLANKS', 'R FIB — Ecosystem', NULL, NULL, NULL, NULL, '{"text":"Every species plays a {{b1}} role in the ecosystem, and the loss of even one can have {{b2}} consequences for the entire {{b3}}.","blanks":[{"id":"b1","answer":"distinct","options":["distinct","useless","random"]},{"id":"b2","answer":"far-reaching","options":["far-reaching","trivial","pleasant"]},{"id":"b3","answer":"community","options":["community","machine","document"]}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_4b0bac47c386d76f', 'READING', 'R_FILL_BLANKS', 'R FIB — Economy', NULL, NULL, NULL, NULL, '{"text":"When interest rates {{b1}}, borrowing becomes more expensive, which tends to {{b2}} consumer spending and slow economic {{b3}}.","blanks":[{"id":"b1","answer":"rise","options":["rise","vanish","sing"]},{"id":"b2","answer":"reduce","options":["reduce","increase","colour"]},{"id":"b3","answer":"growth","options":["growth","silence","weather"]}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_f35cb0b47f1ca93e', 'READING', 'R_FILL_BLANKS', 'R FIB — Language', NULL, NULL, NULL, NULL, '{"text":"Languages {{b1}} constantly, as new words emerge and old ones fall {{b2}} of use, reflecting changes in the surrounding {{b3}}.","blanks":[{"id":"b1","answer":"evolve","options":["evolve","freeze","shrink"]},{"id":"b2","answer":"out","options":["out","in","over"]},{"id":"b3","answer":"culture","options":["culture","machine","planet"]}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_9aad44fa25eee604', 'READING', 'R_FILL_BLANKS', 'R FIB — Health', NULL, NULL, NULL, NULL, '{"text":"A balanced diet {{b1}} the body with essential nutrients, helping to {{b2}} illness and maintain overall {{b3}}.","blanks":[{"id":"b1","answer":"provides","options":["provides","denies","hides"]},{"id":"b2","answer":"prevent","options":["prevent","cause","enjoy"]},{"id":"b3","answer":"wellbeing","options":["wellbeing","confusion","furniture"]}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_27aebeac151ddd2f', 'LISTENING', 'SUMMARIZE_SPOKEN_TEXT', 'SST — Photosynthesis', NULL, 'Photosynthesis is fundamental to life on Earth. Using energy from sunlight, plants convert carbon dioxide and water into glucose, which stores chemical energy, and they release oxygen as a by-product. This single process supplies the food that sustains nearly all ecosystems and produces most of the oxygen we breathe.', NULL, 'audio', '{"transcript":"Photosynthesis is fundamental to life on Earth. Using energy from sunlight, plants convert carbon dioxide and water into glucose, and release oxygen. It supplies food for ecosystems and most of the oxygen we breathe.","keyPoints":["plants use sunlight","convert CO2 and water into glucose","release oxygen","sustains ecosystems"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_75b774914fb00695', 'LISTENING', 'SUMMARIZE_SPOKEN_TEXT', 'SST — The internet', NULL, 'The internet began as a small research network designed to let computers share data reliably even if part of the system failed. Over decades it grew into a global infrastructure connecting billions of devices. Today it underpins commerce, education, and communication, though it also raises pressing questions about privacy and security.', NULL, 'audio', '{"transcript":"The internet began as a small research network built to share data reliably. It grew into global infrastructure connecting billions of devices, underpinning commerce, education, and communication, while raising privacy and security concerns.","keyPoints":["started as research network","grew globally","connects billions of devices","raises privacy and security concerns"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5bec7a1c92b02df7', 'LISTENING', 'SUMMARIZE_SPOKEN_TEXT', 'SST — Vaccines', NULL, 'Vaccines work by training the immune system to recognise a specific pathogen without causing the disease itself. They introduce a harmless component of the microbe, prompting the body to produce protective antibodies. If the real pathogen later appears, the immune system responds quickly, preventing serious illness and helping to protect whole communities.', NULL, 'audio', '{"transcript":"Vaccines train the immune system to recognise a pathogen without causing disease, prompting protective antibodies. If the real pathogen appears, the body responds quickly, preventing serious illness and protecting communities.","keyPoints":["train the immune system","harmless component prompts antibodies","fast response later","protect communities"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_a2570cbd5cdd1bd4', 'LISTENING', 'SUMMARIZE_SPOKEN_TEXT', 'SST — Sleep', NULL, 'Sleep is far from a passive state. While we rest, the brain consolidates memories, clears metabolic waste, and regulates hormones that control appetite and stress. Consistently poor sleep is linked to impaired judgement, weakened immunity, and a higher risk of chronic disease, which is why researchers treat it as a pillar of good health.', NULL, 'audio', '{"transcript":"Sleep is active: the brain consolidates memories, clears waste, and regulates hormones. Poor sleep impairs judgement, weakens immunity, and raises chronic-disease risk, making it a pillar of health.","keyPoints":["sleep is active","consolidates memory and clears waste","regulates hormones","poor sleep harms health"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5555e1f3c5e7b1fb', 'LISTENING', 'SUMMARIZE_SPOKEN_TEXT', 'SST — Deforestation', NULL, 'Deforestation has consequences that extend far beyond the loss of trees. Forests store enormous amounts of carbon, so clearing them releases greenhouse gases and accelerates climate change. They also regulate rainfall and shelter a large share of the planet''s species, meaning their destruction threatens both climate stability and biodiversity.', NULL, 'audio', '{"transcript":"Deforestation releases stored carbon and accelerates climate change. Forests also regulate rainfall and shelter many species, so clearing them threatens both climate stability and biodiversity.","keyPoints":["forests store carbon","clearing releases greenhouse gases","forests regulate rainfall","threatens biodiversity"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_7b07131cf61a6629', 'LISTENING', 'MCQ_MULTI_L', 'L-MCQ (multiple) — Coral reefs', NULL, 'Coral reefs support roughly a quarter of all marine species, provide food for coastal communities, and protect shorelines from storms. Yet they are highly sensitive to rising temperatures and ocean acidification.', NULL, 'audio', '{"question":"According to the recording, coral reefs: (Select all that apply.)","options":[{"id":"a","text":"support many marine species"},{"id":"b","text":"protect shorelines from storms"},{"id":"c","text":"are unaffected by temperature"},{"id":"d","text":"are sensitive to acidification"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_ffd7c8efdb929649', 'LISTENING', 'MCQ_MULTI_L', 'L-MCQ (multiple) — Electric cars', NULL, 'Electric vehicles produce no tailpipe emissions and are cheaper to run than petrol cars. However, their environmental benefit depends on how the electricity is generated, and battery production remains resource-intensive.', NULL, 'audio', '{"question":"The speaker states that electric vehicles: (Select all that apply.)","options":[{"id":"a","text":"produce no tailpipe emissions"},{"id":"b","text":"are cheaper to run"},{"id":"c","text":"always help the environment regardless of electricity"},{"id":"d","text":"rely on resource-intensive batteries"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_c4e4100eaa2751f5', 'LISTENING', 'MCQ_MULTI_L', 'L-MCQ (multiple) — Museums', NULL, 'Interactive museum exhibits can deepen engagement, help visitors remember information, and appeal to younger audiences. Some curators caution, though, that spectacle should not replace scholarly accuracy.', NULL, 'audio', '{"question":"The recording mentions that interactive exhibits: (Select all that apply.)","options":[{"id":"a","text":"deepen engagement"},{"id":"b","text":"help visitors remember"},{"id":"c","text":"guarantee scholarly accuracy"},{"id":"d","text":"appeal to younger audiences"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_90ed630722b46243', 'LISTENING', 'MCQ_MULTI_L', 'L-MCQ (multiple) — Exercise', NULL, 'Regular physical activity strengthens the heart, improves mood, and supports better sleep. The speaker stresses that consistency matters more than intensity for long-term benefits.', NULL, 'audio', '{"question":"According to the speaker, regular exercise: (Select all that apply.)","options":[{"id":"a","text":"strengthens the heart"},{"id":"b","text":"improves mood"},{"id":"c","text":"must always be intense"},{"id":"d","text":"supports better sleep"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_03baf413807128ba', 'LISTENING', 'MCQ_MULTI_L', 'L-MCQ (multiple) — Libraries', NULL, 'Modern libraries lend far more than books; they offer digital resources, community events, and quiet study space. Librarians argue that this broader role makes them more relevant than ever.', NULL, 'audio', '{"question":"The recording says modern libraries offer: (Select all that apply.)","options":[{"id":"a","text":"digital resources"},{"id":"b","text":"community events"},{"id":"c","text":"only printed books"},{"id":"d","text":"quiet study space"}],"correctOptionIds":["a","b","d"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_f848e184ba4636c1', 'LISTENING', 'L_FILL_BLANKS', 'L-FIB — Coral discovery', NULL, 'Scientists have recently discovered a new species of coral thriving in unusually deep water.', NULL, 'audio', '{"text":"Scientists have recently {{b1}} a new {{b2}} of coral thriving in unusually {{b3}} water.","blanks":[{"id":"b1","answer":"discovered"},{"id":"b2","answer":"species"},{"id":"b3","answer":"deep"}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_a1935d6268df9c5a', 'LISTENING', 'L_FILL_BLANKS', 'L-FIB — Lecture attendance', NULL, 'The lecture attracted a large audience because the topic was both timely and controversial.', NULL, 'audio', '{"text":"The lecture attracted a large {{b1}} because the topic was both {{b2}} and {{b3}}.","blanks":[{"id":"b1","answer":"audience"},{"id":"b2","answer":"timely"},{"id":"b3","answer":"controversial"}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0e973c7ce925dce0', 'LISTENING', 'L_FILL_BLANKS', 'L-FIB — Research funding', NULL, 'The government announced additional funding to support research into renewable energy technologies.', NULL, 'audio', '{"text":"The government announced additional {{b1}} to support {{b2}} into renewable {{b3}} technologies.","blanks":[{"id":"b1","answer":"funding"},{"id":"b2","answer":"research"},{"id":"b3","answer":"energy"}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_6699d9bb14ffba06', 'LISTENING', 'L_FILL_BLANKS', 'L-FIB — Ancient trade', NULL, 'Ancient traders travelled vast distances to exchange spices, silk, and precious metals.', NULL, 'audio', '{"text":"Ancient traders travelled vast {{b1}} to exchange spices, {{b2}}, and precious {{b3}}.","blanks":[{"id":"b1","answer":"distances"},{"id":"b2","answer":"silk"},{"id":"b3","answer":"metals"}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_be1132660c2b8bfa', 'LISTENING', 'L_FILL_BLANKS', 'L-FIB — Climate report', NULL, 'The report warned that rising temperatures could threaten crops across several continents.', NULL, 'audio', '{"text":"The report {{b1}} that rising {{b2}} could threaten {{b3}} across several continents.","blanks":[{"id":"b1","answer":"warned"},{"id":"b2","answer":"temperatures"},{"id":"b3","answer":"crops"}]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_ea242b9774a61030', 'LISTENING', 'HIGHLIGHT_SUMMARY', 'HCS — Renewable energy', NULL, 'The speaker explains that although renewable energy sources like wind and solar are clean and increasingly affordable, their variable output means that reliable storage and backup are essential for a stable grid.', NULL, 'audio', '{"options":[{"id":"a","text":"Renewables are clean and cheaper, but their variable output makes storage and backup essential for a stable grid."},{"id":"b","text":"Renewables are too expensive and should be abandoned in favour of coal."},{"id":"c","text":"Wind and solar produce constant output and never need backup."},{"id":"d","text":"The speaker argues that energy storage is unnecessary."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_d8edf38f53d24dc1', 'LISTENING', 'HIGHLIGHT_SUMMARY', 'HCS — Reading', NULL, 'The talk emphasises that regular reading widens vocabulary and improves focus, but the speaker notes it is a support for learning rather than a guarantee of success by itself.', NULL, 'audio', '{"options":[{"id":"a","text":"Reading widens vocabulary and improves focus, supporting learning without guaranteeing success alone."},{"id":"b","text":"Reading has no measurable benefits."},{"id":"c","text":"Reading alone guarantees academic success."},{"id":"d","text":"The speaker discourages reading."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_ca2c50bf32c62a5b', 'LISTENING', 'HIGHLIGHT_SUMMARY', 'HCS — Urbanisation', NULL, 'According to the recording, compact cities can cut car use and protect farmland, yet the speaker acknowledges that higher density may push up housing costs and strain services.', NULL, 'audio', '{"options":[{"id":"a","text":"Compact cities cut car use and protect farmland but may raise housing costs and strain services."},{"id":"b","text":"Compact cities always lower housing costs."},{"id":"c","text":"The speaker opposes all city growth."},{"id":"d","text":"Density has no effect on services."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_410ef0080236b5bf', 'LISTENING', 'HIGHLIGHT_SUMMARY', 'HCS — Sleep', NULL, 'The lecturer describes sleep as an active process during which the brain consolidates memories and clears waste, warning that chronic sleep loss harms both mind and body.', NULL, 'audio', '{"options":[{"id":"a","text":"Sleep is an active process that consolidates memory and clears waste; chronic loss harms mind and body."},{"id":"b","text":"Sleep is a purely passive, unimportant state."},{"id":"c","text":"The lecturer says sleep loss has no effect."},{"id":"d","text":"Sleep only affects mood, nothing else."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_88aad6d9ae2b4f8e', 'LISTENING', 'HIGHLIGHT_SUMMARY', 'HCS — Tourism', NULL, 'The speaker notes that tourism can fund conservation and boost local economies, but warns that excessive visitor numbers can damage fragile sites and raise living costs for residents.', NULL, 'audio', '{"options":[{"id":"a","text":"Tourism can fund conservation and boost economies, but too many visitors can damage sites and raise costs."},{"id":"b","text":"Tourism has only negative effects."},{"id":"c","text":"Tourism never affects local prices."},{"id":"d","text":"The speaker says fragile sites are indestructible."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_2e9ebe9034d5cae7', 'LISTENING', 'MCQ_SINGLE_L', 'L-MCQ (single) — Main idea', NULL, 'In this segment, the speaker argues that the single most effective way for individuals to reduce their carbon footprint is to change how often they fly, since air travel is remarkably carbon-intensive.', NULL, 'audio', '{"question":"What is the speaker''s main point?","options":[{"id":"a","text":"Flying less is a highly effective way to cut one''s carbon footprint."},{"id":"b","text":"Air travel has no climate impact."},{"id":"c","text":"Individuals cannot affect emissions."},{"id":"d","text":"Cars are the only source of emissions."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_6ee28d6c0c9a1c77', 'LISTENING', 'MCQ_SINGLE_L', 'L-MCQ (single) — Purpose', NULL, 'The presenter introduces a new campus recycling scheme, explaining where the new bins are located and which materials each one accepts.', NULL, 'audio', '{"question":"What is the purpose of the talk?","options":[{"id":"a","text":"To explain a new campus recycling scheme."},{"id":"b","text":"To announce exam results."},{"id":"c","text":"To advertise a concert."},{"id":"d","text":"To describe a sports event."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_e9d946af9ecff33b', 'LISTENING', 'MCQ_SINGLE_L', 'L-MCQ (single) — Detail', NULL, 'The researcher reports that the study followed participants for ten years, making it one of the longest investigations of its kind.', NULL, 'audio', '{"question":"How long did the study last?","options":[{"id":"a","text":"Ten years."},{"id":"b","text":"Ten weeks."},{"id":"c","text":"One year."},{"id":"d","text":"Six months."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_eb9934f8ac7199c3', 'LISTENING', 'MCQ_SINGLE_L', 'L-MCQ (single) — Attitude', NULL, 'While acknowledging the risks of artificial intelligence, the speaker remains broadly optimistic that careful regulation can allow society to enjoy its benefits.', NULL, 'audio', '{"question":"What is the speaker''s attitude toward AI?","options":[{"id":"a","text":"Cautiously optimistic."},{"id":"b","text":"Completely dismissive."},{"id":"c","text":"Entirely fearful."},{"id":"d","text":"Uninterested."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5e2ba8ea0a7d3c13', 'LISTENING', 'MCQ_SINGLE_L', 'L-MCQ (single) — Conclusion', NULL, 'The lecturer concludes that, above all, consistent daily practice matters far more than occasional bursts of intense effort when learning a language.', NULL, 'audio', '{"question":"What does the lecturer conclude about language learning?","options":[{"id":"a","text":"Consistent daily practice matters most."},{"id":"b","text":"Only intensive bursts work."},{"id":"c","text":"Practice is unnecessary."},{"id":"d","text":"Grammar is the only thing that matters."}],"correctOptionId":"a"}', 2, 1, '[]', datetime('now'), datetime('now'));
