INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_40a1eb60f653b91b', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Antibiotic resistance', NULL, NULL, NULL, NULL, '{"text":"The overuse of antibiotics in both medicine and agriculture has accelerated the emergence of resistant bacteria, a development that public health researchers describe as one of the most serious long-term threats to modern healthcare."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_41a35621fa992dc5', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Museum collections', NULL, NULL, NULL, NULL, '{"text":"Curators must balance the competing demands of preservation and access, since every hour a fragile manuscript spends on public display slightly shortens the lifespan of the very object visitors have come to admire."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0125ef9c27595c00', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Volcanic ash', NULL, NULL, NULL, NULL, '{"text":"When a volcano erupts violently, it can inject vast quantities of ash and sulphur dioxide into the stratosphere, temporarily cooling the global climate by reflecting a portion of incoming sunlight back into space."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_f6e2cb22f6f3e6e5', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Bilingual education', NULL, NULL, NULL, NULL, '{"text":"Children raised in bilingual households often demonstrate greater cognitive flexibility than their monolingual peers, though researchers continue to debate how much of this advantage persists into adulthood."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_76eb0773cee0d511', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Antarctic research', NULL, NULL, NULL, NULL, '{"text":"Scientists working at Antarctic research stations endure months of isolation and darkness in order to collect ice cores that preserve a detailed atmospheric record stretching back hundreds of thousands of years."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_c36c78fd3b9de4ee', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Urban transport', NULL, NULL, NULL, NULL, '{"text":"Cities that invest heavily in cycling infrastructure typically see a marked reduction in short car journeys, easing congestion and improving air quality without the expense of building new roads."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_6cbb9b8c29a86a65', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Behavioural economics', NULL, NULL, NULL, NULL, '{"text":"Behavioural economists have shown that people frequently make decisions which contradict their own stated preferences, particularly when a choice is presented under time pressure or framed in terms of potential losses."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_0fa6203518583114', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Soil degradation', NULL, NULL, NULL, NULL, '{"text":"Intensive farming can strip soil of organic matter far faster than natural processes replace it, and once fertility declines, restoring the land often takes decades of careful and expensive management."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_241eed88cebc204a', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Peer review', NULL, NULL, NULL, NULL, '{"text":"Although peer review remains the principal safeguard of scientific quality, critics point out that it is slow, largely unpaid, and surprisingly inconsistent in identifying errors within complex statistical analyses."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_9b5aa779df67dc04', 'SPEAKING', 'READ_ALOUD', 'Read Aloud — Ancient trade routes', NULL, NULL, NULL, NULL, '{"text":"The overland routes linking Asia and the Mediterranean carried not only silk and spices but also technologies, religions and diseases, reshaping the societies at both ends far more profoundly than any single commodity."}', 2, 1, '[]', datetime('now'), datetime('now'));
