INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_8b001a8c8107b025', 'WRITING', 'WRITE_ESSAY', 'Essay — Remote work and collaboration', NULL, NULL, NULL, NULL, '{"prompt":"Some people believe that widespread remote working benefits both employees and society, while others argue it weakens collaboration and isolates workers. Discuss both views and give your own opinion."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_9e575efcdfb191dc', 'WRITING', 'WRITE_ESSAY', 'Essay — University fees', NULL, NULL, NULL, NULL, '{"prompt":"Some argue that university education should be free for all students, while others believe those who benefit financially should contribute to its cost. Discuss both positions and state your view."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_219c02ac50faf35c', 'WRITING', 'WRITE_ESSAY', 'Essay — Artificial intelligence at work', NULL, NULL, NULL, NULL, '{"prompt":"Artificial intelligence is increasingly used to make decisions in hiring, lending and healthcare. Do the efficiency gains justify reducing human judgement in these areas? Give reasons for your answer."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_1315b3877159001d', 'WRITING', 'WRITE_ESSAY', 'Essay — Car-free city centres', NULL, NULL, NULL, NULL, '{"prompt":"Several cities have banned private cars from their centres to reduce pollution. Some see this as essential progress; others regard it as unfair to residents and small businesses. Discuss both views and give your opinion."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_679db45781d63183', 'WRITING', 'WRITE_ESSAY', 'Essay — Space exploration spending', NULL, NULL, NULL, NULL, '{"prompt":"Governments spend large sums on space exploration while significant problems remain unsolved on Earth. To what extent do you think this spending is justified?"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_180d1bb849827d59', 'WRITING', 'WRITE_ESSAY', 'Essay — Social media and news', NULL, NULL, NULL, NULL, '{"prompt":"An increasing number of people get their news primarily from social media. Does this development do more to inform the public or to mislead it? Support your position with reasons and examples."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_f88bc41d1ff2ed01', 'WRITING', 'WRITE_ESSAY', 'Essay — Compulsory volunteering', NULL, NULL, NULL, NULL, '{"prompt":"Some countries require secondary school students to complete a period of community service before graduating. Discuss the advantages and disadvantages of making volunteering compulsory, and give your own view."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_9cc6892a9d5c3622', 'WRITING', 'WRITE_ESSAY', 'Essay — Preserving minority languages', NULL, NULL, NULL, NULL, '{"prompt":"Many minority languages are disappearing. Some argue that public money should be spent preserving them; others believe resources are better directed elsewhere. Discuss both views and give your opinion."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5c3a718979a78f82', 'WRITING', 'WRITE_ESSAY', 'Essay — Four-day working week', NULL, NULL, NULL, NULL, '{"prompt":"Several organisations have trialled a four-day working week without reducing pay. Do you think this model should be adopted more widely? Give reasons for your answer."}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_5f99fca681caa82f', 'WRITING', 'WRITE_ESSAY', 'Essay — Tourism and heritage', NULL, NULL, NULL, NULL, '{"prompt":"Mass tourism brings income to historic cities but also damages the sites visitors come to see. To what extent should access to fragile heritage sites be restricted?"}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_d6e80219e73c091f', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Antibiotic resistance', NULL, 'Bacteria reproduce quickly, and each generation carries small genetic variations. When antibiotics are used heavily, the few bacteria that happen to survive pass on their resistance, and within a short time the resistant strain dominates. This is why doctors are now urged to prescribe antibiotics only when they are genuinely necessary, and why patients are told to finish the entire course.', NULL, 'audio', '{"keyPoints":["bacteria reproduce fast with genetic variation","heavy antibiotic use selects for survivors","resistant strains come to dominate","prescribe sparingly and finish the course"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_11ce34919b10e4b9', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Ice cores', NULL, 'Ice sheets build up one snowfall at a time, and each layer traps tiny bubbles of the atmosphere as it existed that year. By drilling deep cores and analysing those bubbles, researchers can reconstruct temperature and carbon dioxide levels going back hundreds of thousands of years. This record is what allows us to say with confidence that current concentrations are unusual.', NULL, 'audio', '{"keyPoints":["ice forms in annual layers","bubbles trap ancient atmosphere","cores reveal past temperature and CO2","shows current levels are unusual"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_e1270bfe64e6ee60', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — The placebo effect', NULL, 'In clinical trials, some patients given an inactive treatment nevertheless improve, an outcome known as the placebo effect. Expectation appears to trigger real physiological changes, including the release of the body''s own painkillers. Because of this, any credible drug trial must compare the new treatment against a placebo rather than against no treatment at all.', NULL, 'audio', '{"keyPoints":["inactive treatment can still produce improvement","expectation causes real physiological change","body releases its own painkillers","trials must compare against placebo"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_da9eba6c11517b52', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Language acquisition', NULL, 'Young children acquire their first language without formal instruction, absorbing complex grammatical rules simply by being surrounded by speech. This ability appears to be strongest in early childhood and declines gradually through adolescence. Linguists disagree about whether this reflects a dedicated biological window or simply the greater time and motivation children devote to listening.', NULL, 'audio', '{"keyPoints":["children learn language without instruction","grammar absorbed from exposure","ability declines after early childhood","debate over biological window versus exposure"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_cfec0a5982a4a005', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Supply and demand', NULL, 'When the price of a good rises, producers generally supply more of it while consumers buy less. The point at which these two tendencies balance is called the equilibrium price. Real markets rarely sit exactly at equilibrium, but the model remains useful because it predicts the direction in which prices will move after a shock.', NULL, 'audio', '{"keyPoints":["higher prices increase supply","higher prices reduce demand","balance point is the equilibrium price","model predicts direction of price movement"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_c2d14ab90d18924a', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Plate tectonics', NULL, 'The Earth''s outer shell is broken into rigid plates that drift slowly over the hotter, softer rock beneath. Where plates pull apart, new crust forms; where they collide, one may be forced beneath the other, building mountain ranges and triggering earthquakes. This single framework explains phenomena that once seemed entirely unrelated.', NULL, 'audio', '{"keyPoints":["outer shell divided into drifting plates","new crust forms where plates separate","collisions build mountains and cause earthquakes","unifies previously unrelated phenomena"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_b32d381fe429df4c', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Cognitive bias', NULL, 'People tend to seek out information that confirms what they already believe, a tendency psychologists call confirmation bias. It operates largely below conscious awareness, which is precisely what makes it difficult to correct. Deliberately seeking evidence that would disprove your position is one of the few strategies shown to reduce its influence.', NULL, 'audio', '{"keyPoints":["people favour information confirming existing beliefs","known as confirmation bias","operates unconsciously and resists correction","actively seeking disconfirming evidence helps"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_3d66db17127771a2', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Vaccination and herd immunity', NULL, 'When a sufficiently large proportion of a population is immune to a disease, the pathogen struggles to find new hosts and transmission slows dramatically. This indirect protection, known as herd immunity, shields those who cannot be vaccinated, such as newborns and people with compromised immune systems. The threshold required depends on how contagious the disease is.', NULL, 'audio', '{"keyPoints":["high immunity slows transmission","called herd immunity","protects those who cannot be vaccinated","threshold depends on contagiousness"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_fce27008090b2a68', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Industrial revolution', NULL, 'The shift from hand production to mechanised factories transformed not just manufacturing but the shape of society itself. Populations moved rapidly from the countryside into rapidly expanding cities, family structures changed, and entirely new social classes emerged. Living standards eventually rose substantially, though for the first generations conditions were often extremely harsh.', NULL, 'audio', '{"keyPoints":["mechanisation replaced hand production","rapid migration to cities","new social classes emerged","harsh conditions before living standards rose"]}', 2, 1, '[]', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO Question (id, section, taskType, title, instructions, promptText, mediaUrl, mediaType, payload, difficulty, isSample, tags, createdAt, updatedAt) VALUES ('q_fa41cad8f554355c', 'SPEAKING', 'RETELL_LECTURE', 'Re-tell — Biodiversity and stability', NULL, 'Ecosystems containing many different species tend to withstand disturbance better than simplified ones. If several species perform a similar role, the loss of one can be absorbed because others continue the function. This redundancy is one reason ecologists argue that protecting biodiversity is a practical matter of resilience, not merely an aesthetic preference.', NULL, 'audio', '{"keyPoints":["diverse ecosystems resist disturbance better","overlapping roles provide redundancy","loss of one species can be absorbed","biodiversity supports practical resilience"]}', 2, 1, '[]', datetime('now'), datetime('now'));
